INSERT INTO papers (id, exam_level, year, month, set_no, variant, title, is_demo, status, content_state, source_url, content_kind, description, reference_paper_id) VALUES ('original-cet4-2026-1', 'CET4', 2026, 10, 1, '主题练习', '四级主题练习 01 · 技术与合作', FALSE, 'published', 'local', 'https://pastpapers.cn/paper/2026-06-cet4-1', 'original', '原创缩编练习，学习情境为虚构，覆盖非听力题型。主题参考：校园技术、消费选择与合作。', NULL) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, content_state=EXCLUDED.content_state, source_url=EXCLUDED.source_url, content_kind=EXCLUDED.content_kind, description=EXCLUDED.description, reference_paper_id=EXCLUDED.reference_paper_id, status=EXCLUDED.status;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-1-section-1', 'original-cet4-2026-1', 0, 'writing', '写作', '按题目要求完成写作。提交后查看参考范文，自行核对。', '[]', '["A useful campus library should make routine tasks easy without making students feel that they are speaking only to machines. I propose a simple online reservation system for group study rooms. Students could see available times and receive a reminder before their booking. This would reduce queues and help them plan meetings. However, the library should also keep a desk where students can ask a person for help. New users may not understand the system, and some students may need special arrangements. Staff could collect common questions and use them to improve the website. The university should test the service in one building first and invite feedback after a month. Technology would then support a better service rather than become the only way to receive it."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-1-section-1-q-1', 'original-cet4-2026-1-section-1', 0, 'text', 'Write 120–180 words proposing one way for a campus library to use technology while keeping personal help available.', '[]', 'A useful campus library should make routine tasks easy without making students feel that they are speaking only to machines. I propose a simple online reservation system for group study rooms. Students could see available times and receive a reminder before their booking. This would reduce queues and help them plan meetings. However, the library should also keep a desk where students can ask a person for help. New users may not understand the system, and some students may need special arrangements. Staff could collect common questions and use them to improve the website. The university should test the service in one building first and invite feedback after a month. Technology would then support a better service rather than become the only way to receive it.', '核对是否提出具体措施、解释用途并讨论人工支持；范文采用“建议—好处—边界—试点”的结构。', 10) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-1-section-2', 'original-cet4-2026-1', 1, 'cloze', '选词填空', '从词库选词，每词只用一次。', '["When a college bought a machine to carry books, staff expected an immediate improvement. Instead, students were [1] ______ by the pickup messages. The library invited them to [2] ______ the problem and then changed the signs. A worker still checked each delivery, because a machine could not judge whether a damaged book needed [3] ______ handling. After two weeks, the service became more [4] ______. The lesson was simple: a new device creates value only when people can [5] ______ how to use it."]', '["When a college bought a machine to carry books, staff expected an immediate improvement. Instead, students were confused by the pickup messages. The library invited them to describe the problem and then changed the signs. A worker still checked each delivery, because a machine could not judge whether a damaged book needed careful handling. After two weeks, the service became more reliable. The lesson was simple: a new device creates value only when people can understand how to use it."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
