INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-1-section-3', 'original-cet4-2026-1', 2, 'matching', '信息匹配 · 校园共享', '根据段落内容完成匹配。', '["[A] The repair club meets on Friday afternoons. Students bring broken lamps or bags instead of throwing them away. Before anyone touches a tool, a volunteer explains the basic safety rules. Some items cannot be repaired, but visitors still learn why they failed.","[B] The food-sharing team posts an ingredient list beside every donated meal. People can choose what suits them and leave unsuitable food for someone else. The team asks donors to label the time of preparation as well. Clear information matters more than a large number of donations.","[C] The evening walking group welcomes students who dislike competitive sports. Nobody records a finishing time, and the route has several places to rest. Members usually talk about classes while walking. The organiser believes that a comfortable first experience makes returning easier.","[D] A small lending shelf holds umbrellas and chargers. Borrowers write down what they take and return it when finished. At the end of each week, volunteers check which items are missing or broken. The records help them decide what to buy next."]', '["The repair club meets on Friday afternoons. Students bring broken lamps or bags instead of throwing them away. Before anyone touches a tool, a volunteer explains the basic safety rules. Some items cannot be repaired, but visitors still learn why they failed.","The food-sharing team posts an ingredient list beside every donated meal. People can choose what suits them and leave unsuitable food for someone else. The team asks donors to label the time of preparation as well. Clear information matters more than a large number of donations.","The evening walking group welcomes students who dislike competitive sports. Nobody records a finishing time, and the route has several places to rest. Members usually talk about classes while walking. The organiser believes that a comfortable first experience makes returning easier.","A small lending shelf holds umbrellas and chargers. Borrowers write down what they take and return it when finished. At the end of each week, volunteers check which items are missing or broken. The records help them decide what to buy next."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
