INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('original-cet4-2026-1-section-4-sentence-1-4', 'original-cet4-2026-1', 300, 3, 'The green labels looked impressive, but they did not answer Nora''s questions about freshness or price.', 'original-cet4-2026-1-section-4') ON CONFLICT (id) DO UPDATE SET source_text=EXCLUDED.source_text, section_id=EXCLUDED.section_id;
