INSERT INTO sentences (id,paper_id,paragraph_index,sentence_index,source_text,section_id) VALUES ('original-cet4-2026-1-section-4-sentence-2-5', 'original-cet4-2026-1', 301, 4, 'A label might tell buyers something important, but it could not replace every other question.', 'original-cet4-2026-1-section-4') ON CONFLICT (id) DO UPDATE SET source_text=EXCLUDED.source_text, section_id=EXCLUDED.section_id;
INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-1-section-5', 'original-cet4-2026-1', 4, 'reading', '阅读理解 · A job nobody owned', '阅读短文，选择最合适的答案。', '["Four students organised a weekend book sale. Each selected an enjoyable task, such as designing posters or arranging books. Nobody volunteered to carry the boxes home afterwards. When the sale ended, the boxes remained beside the entrance, and everyone thought someone else would remove them.","For the next event, the group listed every job before dividing the work. They paired popular tasks with less popular ones and allowed members to exchange assignments. They also agreed on a final check before leaving. The change did not require anyone to become more generous overnight. It made the responsibilities visible, so a willing team could turn good intentions into finished work."]', '["Four students organised a weekend book sale. Each selected an enjoyable task, such as designing posters or arranging books. Nobody volunteered to carry the boxes home afterwards. When the sale ended, the boxes remained beside the entrance, and everyone thought someone else would remove them.","For the next event, the group listed every job before dividing the work. They paired popular tasks with less popular ones and allowed members to exchange assignments. They also agreed on a final check before leaving. The change did not require anyone to become more generous overnight. It made the responsibilities visible, so a willing team could turn good intentions into finished work."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-1-section-5-q-1', 'original-cet4-2026-1-section-5', 0, 'choice', 'Why were the boxes left at the entrance?', '[{"key":"A","text":"They belonged to the library."},{"key":"B","text":"The students had no transport."},{"key":"C","text":"The final task had not been assigned."},{"key":"D","text":"The sale was still running."}]', 'C', '搬箱子的职责无人认领，每个人都以为别人会处理。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-1-section-5-q-2', 'original-cet4-2026-1-section-5', 1, 'choice', 'What did the group change?', '[{"key":"A","text":"They made a complete task list and shared responsibilities."},{"key":"B","text":"They cancelled all enjoyable work."},{"key":"C","text":"They selected a new building."},{"key":"D","text":"They stopped allowing exchanges."}]', 'A', '第二次活动明确列出全部工作并允许交换任务。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
INSERT INTO questions (id,section_id,position,type,prompt,options_json,answer_text,explanation,points) VALUES ('original-cet4-2026-1-section-5-q-3', 'original-cet4-2026-1-section-5', 2, 'choice', 'The last paragraph suggests that cooperation benefits from _____.', '[{"key":"A","text":"competition for public attention"},{"key":"B","text":"clear arrangements"},{"key":"C","text":"a larger entrance"},{"key":"D","text":"avoiding difficult tasks"}]', 'B', '清楚的责任安排使合作意愿转化为实际完成。', 2) ON CONFLICT (id) DO UPDATE SET prompt=EXCLUDED.prompt, options_json=EXCLUDED.options_json, answer_text=EXCLUDED.answer_text, explanation=EXCLUDED.explanation, points=EXCLUDED.points;
