INSERT INTO paper_sections (id,paper_id,position,kind,title,instructions,paragraphs_json,study_paragraphs_json) VALUES ('original-cet4-2026-1-section-6', 'original-cet4-2026-1', 5, 'translation', '翻译 · 中译英', '完成翻译，提交后查看参考译文。', '["校园里的一间旧教室被改造成了共享修理室。学生可以在志愿者的帮助下修理日常用品，也可以把不再使用的工具捐给其他人。这个小空间不仅减少了浪费，还让不同专业的学生有机会一起解决实际问题。"]', '["An old classroom on campus has been turned into a shared repair room. Students can repair everyday items with help from volunteers, or donate tools they no longer use. This small space reduces waste and gives students from different majors a chance to solve practical problems together."]') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, instructions=EXCLUDED.instructions, paragraphs_json=EXCLUDED.paragraphs_json, study_paragraphs_json=EXCLUDED.study_paragraphs_json;
